head.script:
scwin.updateCanvasBackground = function () {
    if (!scwin.isWhiteboardActive) return;

    const screenSharePeer = Array.from(scwin.remotePeers.values()).find(p => p.isScreenShare);
    const isScreenShareActive = scwin.localScreenShareElement || screenSharePeer;

    // isCanvasOverlayActive 플래그를 여기서 업데이트 해주는 것이 좋습니다.
    scwin.isCanvasOverlayActive = !!isScreenShareActive;

    scwin.canvasLayer.classList.toggle('standalone', !isScreenShareActive);
};


scwin.throttle = function (callback, delay) {
    let lastCall = 0;
    return function () {
        const now = new Date().getTime();
        if (now - lastCall >= delay) {
            lastCall = now;
            callback();
        }
    };
}

scwin.centerPopup = function (popupId, offsetY = 0) {
    const pop = $p.getPopup(popupId);
    if (pop) {
        const width = pop.popupWin.getSize("width");
        const height = pop.popupWin.getSize("height");
        const left1 = (top.window.innerWidth - width) / 2;
        const top1 = (top.window.innerHeight - height) / 2 + offsetY;
        pop.popupWin.setPosition(left1, top1);
    }
};

scwin.createPopUp = function (_id, _name, _jsnData, url, _popupWidth, _popupHeight) {
    if ($p.getPopup(_id)) {
        console.log(`Popup with ID '${_id}' already exists. Skipping creation.`);
        return;
    }
    var popupWidth = _popupWidth;
    var popupHeight = _popupHeight;
    var topPosition = (window.innerHeight - popupHeight) / 2;
    var leftPosition = (window.innerWidth - popupWidth) / 2;
    var options = {
        id: _id,
        type: "wframePopup",
        width: popupWidth + "px",
        height: popupHeight + "px",
        top: topPosition + "px",
        left: leftPosition + "px",
        popupName: _name,
        modal: true,
        closeAction: "scwin.popup_closeAction",
        dataObject: _jsnData
    };
    $p.openPopup(url, options);
}

scwin.checkAppReady = function () {
    return new Promise(resolve => {
        const interval = setInterval(() => {
            if (window.App && window.App.UIManager && window.App.RoomClient) {
                clearInterval(interval);
                resolve();
            }
        }, 50);
    });
};

scwin.updateVideoLayout = function () {
    const localVideoWrapper = scwin.uiManager.localMediaContainer;
    const mainStageElements = [];
    const sidebarElements = [];

    // 해결: screenShareElement를 사용하는 코드보다 먼저 선언합니다.
    const screenSharePeer = Array.from(scwin.remotePeers.values()).find(p => p.isScreenShare);
    const screenShareElement = scwin.localScreenShareElement || screenSharePeer?.screenShareElement;

    // 1. 로컬 비디오 위치 결정 로직 수정
    if (screenShareElement || (scwin.isWhiteboardActive && !scwin.isCanvasOverlayActive)) {
        // 화면 공유가 있거나, 칠판이 '단독 모드'일 때만 로컬 비디오를 사이드바로 이동
        sidebarElements.push(localVideoWrapper);
    } else {
        // 그 외의 모든 경우(로컬 비디오만 있거나, 칠판이 꺼져있을 때)는 메인에 배치
        mainStageElements.push(localVideoWrapper);
    }

    // 2. 메인 스테이지 요소 결정 로직 수정
    let mainElement = null;

    // 화면 공유를 최우선으로 배치
    if (screenShareElement) {
        mainElement = screenShareElement;
        mainElement.classList.add("screen-share-layer");
    } 
    // 화면 공유가 없을 때, 핀 고정된 비디오가 있다면 배치
    else if (scwin.pinnedProducerId) {
        const pinnedPeer = Array.from(scwin.remotePeers.values()).find(p => p.videoProducerId === scwin.pinnedProducerId);
        if (pinnedPeer) {
            mainElement = pinnedPeer.elementWrapper;
            mainElement.classList.add("pinned-video-layer");
        }
    } 
    // 화면 공유도, 핀 고정도 없을 때 (칠판 단독 모드 포함)
    else {
        // 칠판 단독 모드가 아니라면, 첫 번째 원격 사용자를 메인에 배치
        if (!(scwin.isWhiteboardActive && !scwin.isCanvasOverlayActive)) {
            const firstRemoteVideo = Array.from(scwin.remotePeers.values())
                .filter(p => p.elementWrapper && !p.isScreenShare)
                .map(p => p.elementWrapper)[0];

            if (firstRemoteVideo) {
                mainElement = firstRemoteVideo;
                mainElement.classList.add("pinned-video-layer");
            } else if (!mainStageElements.includes(localVideoWrapper)) {
                // 원격 사용자도 없으면 로컬 비디오를 메인에 배치
                mainElement = localVideoWrapper;
                mainElement.classList.add("pinned-video-layer");
            }
        }
        // 칠판 단독 모드라면 mainElement는 null을 유지
    }

    // 메인 요소가 결정되면 mainStageElements에 추가 (중복 방지)
    if (mainElement && !mainStageElements.includes(mainElement)) {
        mainStageElements.push(mainElement);
    }

    // UIManager가 레이아웃을 업데이트할 때 canvasLayer를 제거하지 않도록 목록에 포함시킵니다.
    mainStageElements.push(scwin.canvasLayer);


    // 4. 나머지 모든 비디오들을 사이드바에 추가
    Array.from(scwin.remotePeers.values()).forEach(peer => {
        if (peer.elementWrapper && !mainStageElements.includes(peer.elementWrapper) && !sidebarElements.includes(peer.elementWrapper)) {
            sidebarElements.push(peer.elementWrapper);
        }
    });

    // 5. UIManager의 updateVideoLayout 함수 호출
    scwin.uiManager.updateVideoLayout(mainStageElements, sidebarElements);

    // 캔버스 레이어는 항상 메인 스테이지에 유지 (초기 로드 시 한 번만 추가되므로 이 로직은 제거)
};

scwin.onpageload = async function () {
    top.window.onresize = scwin.throttle(function () {
        scwin.centerPopup("drowsinessPopUp", 0);
        scwin.centerPopup("adfPopUp", 50);
    }, 200);

    await scwin.checkAppReady();
    console.log("Application classes are loaded. Application starting...");
    const { UIManager, RoomClient, loadModule } = window.App;
    scwin.loadModule = loadModule;

    scwin.uiManager = new UIManager();
    const roomClient = new RoomClient(scwin.uiManager);

    let aiModule = null;
    scwin.canvasModule = null;
    let wsInstance = null;

    scwin.pinnedProducerId = null;
    scwin.localVideoElement = scwin.uiManager.localMediaContainer; // localMediaContainer를 참조하도록 수정
    scwin.localScreenShareElement = null;
    scwin.remotePeers = new Map();

    let isAudioEnabled = true;
    let isVideoEnabled = true; // isVideoEnabled는 RoomClient에서 관리되므로, 여기서는 초기 상태만 설정
    scwin.isScreenSharing = false;
    scwin.isWhiteboardActive = false;

    scwin.isCanvasOverlayActive = false;
    let isAdmin = false;

    // 해결: 이 변수들을 onpageload 함수의 공용 스코프로 이동합니다.
    const userHasAiModule = true;
    const userHasCanvasModule = true;
    const userHasScreenShareModule = true;

    const CANVAS_WEBSOCKET_URL = 'wss://' + location.host + '/InsWebApp/signal.do';
    const CANVAS_WORKER_URL = '/InsWebApp/js/canvas/canvas-worker.js';
    const MEDIA_PIPE_WORKER_URL = '/InsWebApp/media/dist/mediapipe.worker.bundle.js';

    const mainStage = scwin.uiManager.getMainStageContainer();

    // 1. 칠판 레이어(canvasLayer)를 생성하고 모든 레이어 스타일을 적용
    scwin.canvasLayer = document.createElement("div");
    scwin.canvasLayer.id = "canvasLayer";
    scwin.canvasLayer.className = "main-stage-layer canvas-layer";
    scwin.canvasLayer.style.display = 'none';
    scwin.canvasLayer.style.position = 'absolute';
    scwin.canvasLayer.style.top = '0';
    scwin.canvasLayer.style.left = '0';
    scwin.canvasLayer.style.width = '100%';
    scwin.canvasLayer.style.height = '100%';
    scwin.canvasLayer.style.zIndex = '10';
    scwin.canvasLayer.style.overflow = 'hidden';

    // 2. CanvasModule이 사용할 내부 컨테이너를 별도로 생성
    const canvasModuleContainer = document.createElement("div");
    canvasModuleContainer.style.width = "100%";
    canvasModuleContainer.style.height = "100%";
    scwin.canvasLayer.appendChild(canvasModuleContainer); // 칠판 레이어 안에 추가

    // 3. 메인 스테이지에 칠판 레이어 추가 (기존과 동일)
    mainStage.appendChild(scwin.canvasLayer);

    try {
        let CanvasModule = await scwin.loadModule("/InsWebApp/media/dist/modules/canvas.bundle.js", "CanvasModule");
        if (CanvasModule && !CanvasModule.prototype) {
            CanvasModule = CanvasModule.CanvasModule || CanvasModule.default;
        }
        // 해결: 새로 만든 내부 컨테이너를 전달합니다.
        scwin.canvasModule = new CanvasModule(canvasModuleContainer, CANVAS_WEBSOCKET_URL, CANVAS_WORKER_URL);
    } catch (e) {
        console.error("초기 CanvasModule 로드 실패:", e);
    }

    roomClient.on("connected", (ws) => {
        wsInstance = ws;
        if (userHasCanvasModule) {
            scwin.uiManager.showWhiteboardButton();
        }
    });

    roomClient.on("canvas", (data) => {
        if (data.type === "activate") {
            scwin.isWhiteboardActive = true;
            scwin.canvasLayer.style.display = 'block';
            scwin.uiManager.whiteboardButton.textContent = "칠판 끄기";
        } else if (data.type === "deactivate") {
            scwin.isWhiteboardActive = false;
            scwin.canvasLayer.style.display = 'none';
            scwin.uiManager.whiteboardButton.textContent = "칠판";
        } else if (scwin.canvasModule) {
            scwin.canvasModule.signal(data);
        }
        // 칠판이 켜지거나 꺼질 때마다 배경 상태와 비디오 레이아웃을 업데이트합니다.
        // 순서 변경: 배경 상태를 먼저 업데이트
        scwin.updateCanvasBackground();
        scwin.updateVideoLayout();
    });

    roomClient.on("adminStatus", (adminStatus) => {
        isAdmin = adminStatus;
        if (isAdmin) {
            scwin.uiManager.whiteboardButton.onclick = () => {
                const activate = !scwin.isWhiteboardActive;
                wsInstance.send(JSON.stringify({ action: "canvas", data: { type: activate ? "activate" : "deactivate" } }));
            };
            // 화면 공유 버튼 로직은 그대로 유지
            scwin.uiManager.enableScreenSharing(() => {
                if (scwin.isScreenSharing) roomClient.stopScreenShare();
                else roomClient.startScreenShare();
            });
        } else {
            scwin.uiManager.hideWhiteboardButton();
            scwin.uiManager.disableScreenSharing();
        }
    });

    roomClient.on("screenShareState", ({ isSharing }) => {
        scwin.isScreenSharing = isSharing;
        scwin.uiManager.screenShareButton.textContent = isSharing ? "공유 중지" : "화면 공유";
        // 순서 변경: 배경 상태를 먼저 업데이트
        scwin.updateCanvasBackground();
        scwin.updateVideoLayout();
    });

    roomClient.on("controlsReady", () => {
        scwin.uiManager.enableControls();
        scwin.uiManager.cameraOffButton.onclick = () => {
            isVideoEnabled = !isVideoEnabled;
            roomClient.setVideoEnabled(isVideoEnabled);
            scwin.uiManager.cameraOffButton.textContent = isVideoEnabled ? "카메라 끄기" : "카메라 켜기";
            // 로컬 비디오 컨테이너에 video-paused 클래스 토글
            // scwin.uiManager.localMediaContainer.classList.toggle('video-paused', !isVideoEnabled); // 이 줄을 제거합니다.
        };
        scwin.uiManager.muteButton.onclick = () => {
            isAudioEnabled = !isAudioEnabled;
            roomClient.setAudioEnabled(isAudioEnabled);
            scwin.uiManager.muteButton.textContent = isAudioEnabled ? "음소거" : "음소거 해제";
        };
    });

    // RoomClient에서 로컬 비디오 상태 변경 이벤트를 수신하여 UIManager에 전달
    roomClient.on("localVideoStateChanged", (isEnabled) => {
        scwin.uiManager.updateLocalVideoState(isEnabled);
    });

    roomClient.on("localStreamReady", (videoElement) => {
        scwin.localVideoElement = scwin.uiManager.localMediaContainer; // localMediaContainer를 참조하도록 수정

        if (userHasAiModule) {
            try {
                scwin.loadModule(
                    "/InsWebApp/media/dist/modules/mediapipe.bundle.js",
                    "MediaPipeModule"
                ).then(MediaPipeModule => {
                    if (MediaPipeModule && !MediaPipeModule.prototype) {
                        MediaPipeModule = MediaPipeModule.MediaPipeModule || MediaPipeModule.default;
                    }
                    aiModule = new MediaPipeModule(videoElement, MEDIA_PIPE_WORKER_URL);
                    console.log("AI Module will be initialized.");

                    if (aiModule) aiModule.start();

                    aiModule.on("landmarksUpdate", (landmarks) => {
                        scwin.uiManager.drawFaceMesh(landmarks);
                    });

                    aiModule.on("drowsinessDetected", (data) => {
                        console.log("Event: drowsinessUpdate -> Sending status to server.");
                        scwin.createPopUp("drowsinessPopUp", "Warning !!", null, "/InsWebApp/ui/media_pipe_pop_up/drowsiness_pop_up.xml", 400, 425);
                        roomClient.sendPeerStatus(data);
                    });
                    aiModule.on("drowsinessResolved", (data) => {
                        console.log("Event: drowsinessUpdate -> Sending status to server.");
                        roomClient.sendPeerStatus(data);
                    });

                    aiModule.on("absenceStarted", (data) => {
                        console.log(" Event: absenceStarted -> Sending status to server.");
                        scwin.createPopUp("adfPopUp", "Warning !!", null, "/InsWebApp/ui/media_pipe_pop_up/adf_pop_up.xml", 400, 475);
                        roomClient.sendPeerStatus(data);
                    });
                    aiModule.on("absenceEnded", (data) => {
                        console.log(" Event: absenceEnded -> Sending status to server.");
                        roomClient.sendPeerStatus(data);
                    });

                    aiModule.on("error", (error) => {
                        console.error(" AI Module Error:", error);
                    });
                });
            } catch (error) {
                console.error("Failed to load MediaPipeModule:", error);
            }
        }

        scwin.updateVideoLayout();
    });

    roomClient.on("new-consumer", async (consumer) => {
        const { track, producerId, appData } = consumer;
        const peerId = appData.peerId;
        if (!peerId) return;

        let peer = scwin.remotePeers.get(peerId);
        if (!peer) {
            // 화면 공유 속성 추가
            peer = {
                videoProducerId: null,
                audioProducerId: null,
                screenShareProducerId: null, // 추가
                elementWrapper: null,
                audioElement: null,
                screenShareElement: null, // 추가
                isScreenShare: false
            };
            scwin.remotePeers.set(peerId, peer);
        }

        if (appData && appData.source === 'screen') {
            peer.isScreenShare = true;
            // 카메라와 분리된 전용 속성에 ID 저장
            peer.screenShareProducerId = producerId;

            const elementWrapper = document.createElement("div");
            elementWrapper.id = `remote-screen-${producerId}`;
            const videoEl = document.createElement(track.kind);
            videoEl.srcObject = new MediaStream([track]);
            videoEl.autoplay = true;
            videoEl.playsInline = true;
            elementWrapper.appendChild(videoEl);

            // 전용 속성에 DOM 요소 저장
            peer.screenShareElement = elementWrapper;

            if (peerId === scwin.myPeerId) {
                // 관리자의 경우 localScreenShareElement도 세팅 (필요 시)
                scwin.localScreenShareElement = elementWrapper;
            }
            scwin.updateCanvasBackground();
        } else if (track.kind === 'video') {
            peer.videoProducerId = producerId;

            if (!peer.elementWrapper) {
                const elementWrapper = document.createElement('div');
                elementWrapper.id = `remote-peer-${peerId}`;
                elementWrapper.onclick = () => {
                    if (scwin.isScreenSharing || scwin.isWhiteboardActive) {
                        alert("화면 공유 또는 칠판이 활성화된 중에는 다른 화면을 고정할 수 없습니다.");
                        return;
                    }
                    scwin.pinnedProducerId = (scwin.pinnedProducerId === peer.videoProducerId) ? null : peer.videoProducerId;
                    scwin.updateVideoLayout();
                };
                peer.elementWrapper = elementWrapper;
            }

            const videoEl = document.createElement('video');
            videoEl.srcObject = new MediaStream([track]);
            videoEl.autoplay = true;
            videoEl.playsInline = true;
            peer.elementWrapper.appendChild(videoEl);

        } else if (track.kind === 'audio') {
            peer.audioProducerId = producerId;
            const audioEl = document.createElement('audio');
            audioEl.id = `remote-audio-${producerId}`;
            audioEl.srcObject = new MediaStream([track]);
            audioEl.autoplay = true;
            document.body.appendChild(audioEl);
            peer.audioElement = audioEl;
        }
        scwin.updateVideoLayout();
    });

    roomClient.on("producer-closed", ({ producerId, isScreenShareProducer, isLocalVideoProducer, peerId }) => {
        if (peerId) {
            const peer = scwin.remotePeers.get(peerId);
            if (peer) {
                // 화면 공유 스트림 종료 처리
                if (peer.screenShareProducerId === producerId) {
                    if (peer.screenShareElement) {
                        peer.screenShareElement.remove();
                        peer.screenShareElement = null;
                    }
                    peer.screenShareProducerId = null;
                    peer.isScreenShare = false; // 상태 플래그도 초기화
                }
                // 카메라 스트림 종료 처리 (기존 로직 유지)
                if (peer.videoProducerId === producerId) {
                    if (peer.elementWrapper) {
                        peer.elementWrapper.remove();
                        peer.elementWrapper = null;
                    }
                    peer.videoProducerId = null;
                }
                // ... (기존 오디오 처리 로직 유지) ...
                if (peer.audioProducerId === producerId) {
                    if (peer.audioElement) {
                        peer.audioElement.remove();
                        peer.audioElement = null;
                    }
                    peer.audioProducerId = null;
                }

                if (!peer.videoProducerId && !peer.audioProducerId && !peer.screenShareProducerId) {
                    scwin.remotePeers.delete(peerId);
                }
            }
        }

        if (isScreenShareProducer) {
            // 로컬 화면 공유가 닫혔을 때 처리
            if (scwin.localScreenShareElement && isLocalVideoProducer) { // isLocalVideoProducer는 로컬 비디오 프로듀서가 닫혔을 때 true
                scwin.localScreenShareElement.remove();
                scwin.localScreenShareElement = null;
            }
            scwin.updateCanvasBackground();
        }

        if (scwin.pinnedProducerId === producerId) {
            scwin.pinnedProducerId = null;
        }
        scwin.updateVideoLayout();
    });

    roomClient.on("local-screen-share-started", (track) => {
        const screenShareWrapper = document.createElement("div");
        screenShareWrapper.id = "local-screen-share-wrapper";
        const element = document.createElement(track.kind);
        element.srcObject = new MediaStream([track]);
        element.muted = true;
        element.autoplay = true;
        element.playsInline = true;
        screenShareWrapper.appendChild(element);

        scwin.localScreenShareElement = screenShareWrapper;
        scwin.updateVideoLayout();
    });

    roomClient.on("local-screen-share-stopped", () => {
        if (scwin.localScreenShareElement) {
            scwin.localScreenShareElement.remove();
            scwin.localScreenShareElement = null;
        }
        scwin.updateVideoLayout();
    });

    roomClient.on("remote-producer-pause", ({ producerId }) => {
        for (const [peerId, peer] of scwin.remotePeers.entries()) {
            if (peer.videoProducerId === producerId && peer.elementWrapper) {
                peer.elementWrapper.classList.add('video-paused');
                console.log(`[PAUSE] video-paused class added to peer ${peerId}`, peer.elementWrapper);
                break;
            }
        }
    });

    roomClient.on("remote-producer-resume", ({ producerId }) => {
        for (const [peerId, peer] of scwin.remotePeers.entries()) {
            if (peer.videoProducerId === producerId && peer.elementWrapper) {
                peer.elementWrapper.classList.remove('video-paused');
                console.log(`[RESUME] video-paused class removed from peer ${peerId}`, peer.elementWrapper);
                break;
            }
        }
    });

    const roomId = "my-first";
    roomClient.join(roomId);
};
